// Entrada do RPA: { clientes: [...] } - 1 item por cliente
const body = $input.first().json.body || $input.first().json;
const clientes = body.clientes || body || [];
if (!Array.isArray(clientes) || !clientes.length) throw new Error('Webhook sem clientes: esperado { clientes: [...] }');
return clientes.map(c => ({ json: { nome:String(c.nome||'').trim(), email:String(c.email||'').trim(), saldo:String(c.saldo||'').trim(), perfil:String(c.perfil||'').trim() } }));

// Cruza Clientes x Investimentos - data.csv LOCAL (RPA/docs/data.csv via http://localhost:8000/data.csv)
// Entrada: 1 cliente por vez (vem de Dividir). CSV vem do node HTTP Request - data.csv.
// Regra: mesmo perfil E saldo >= minimo. Fallback: menor minimo do perfil.
const cliente = $input.first().json;
const csv = $('HTTP Request - data.csv').first().json.data || '';
const saldoNum = Number(String(cliente.saldo).replace('R$','').replace(/\./g,'').replace(',','.').trim()) || 0;
const produtos = String(csv).trim().split(/\r?\n/).slice(1).map(l => { const [perfil,produto,minimo,rentabilidade] = l.split(','); return {perfil:perfil?.trim(),produto:produto?.trim(),minimo:Number(minimo)||0,rentabilidade:rentabilidade?.trim()}; });
let elegiveis = produtos.filter(p => p.perfil===cliente.perfil && saldoNum>=p.minimo);
if (!elegiveis.length) elegiveis = produtos.filter(p=>p.perfil===cliente.perfil).sort((a,b)=>a.minimo-b.minimo).slice(0,1);
return [{ json:{ ...cliente, saldo_num:saldoNum, email_valido:/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cliente.email), produtos:elegiveis, produto_principal:elegiveis[0]?.produto||'', rentabilidade_principal:elegiveis[0]?.rentabilidade||'' } }];

// Gera mensagem personalizada por TEMPLATE (sem custo de LLM).
// Para usar LLM: troque este node por 'Message a model' e use $json.prompt como entrada.
return $input.all().map(({json:c})=>{
  const lista = c.produtos.map(p=>`- ${p.produto} (minimo R$ ${p.minimo} | rentabilidade ${p.rentabilidade})`).join('
');
  const prompt = `Voce e um assessor de investimentos. Gere um briefing curto, sem promessas de rentabilidade, para: ${c.nome} | Perfil ${c.perfil} | Saldo ${c.saldo}. Produtos compativeis: ${lista}. Maximo 120 palavras.`;
  const body = `Ola ${c.nome},

Com base no seu perfil ${c.perfil} e saldo atual de ${c.saldo}, separamos opcoes compativeis com voce:
${lista}

Destaque: ${c.produto_principal} (${c.rentabilidade_principal}).

Este e-mail e informativo e nao garante rentabilidade. Fale com seu assessor antes de investir.

Equipe RPA + n8n - DIO`;
  return {json:{...c, prompt, subject:`Sugestao de Investimento para voce, ${c.nome} | ${c.produto_principal}`, body}};
});
